1	import React, { useEffect, useState } from 'react';
2	import type { Feature } from '../../router/routes';
3	
4	// Projects feature: add a project and pick which client it is for, then list every project showing
5	// the client's NAME. Opening a project (project-open-<id>) reveals its detail: the invoices raised
6	// against it, their running total, and a form to add another. Owns its own state; talks to its own
7	// /api/projects and /api/invoices endpoints and reads /api/clients to populate the client picker.
8	// data-testid anchors follow the spec's conventions.
9	type Client = { id: number; name: string; email: string };
10	type Project = { id: number; name: string; clientId: number; clientName: string };
11	type Invoice = { id: number; projectId: number; amount: number; status: string };
12	
13	function money(amount: number): string {
14	  return `$${Number(amount).toFixed(2)}`;
15	}
16	
17	// A project's detail: its invoices, what they add up to, and a form to add a new invoice. Owns its
18	// own invoice state, scoped to the one project it is showing.
19	function ProjectDetail({ project }: { project: Project }) {
20	  const [invoices, setInvoices] = useState<Invoice[]>([]);
21	  const [amount, setAmount] = useState('');
22	  const [amountError, setAmountError] = useState('');
23	
24	  async function load() {
25	    const res = await fetch(`/api/invoices?projectId=${project.id}`);
26	    setInvoices(await res.json());
27	  }
28	
29	  useEffect(() => {
30	    void load();
31	  }, [project.id]);
32	
33	  async function submit(e: React.FormEvent) {
34	    e.preventDefault();
35	    const value = Number(amount);
36	    if (amount.trim() === '' || !Number.isFinite(value) || value <= 0) {
37	      setAmountError('Amount must be more than zero');
38	      return;
39	    }
40	    setAmountError('');
41	    await fetch('/api/invoices', {
42	      method: 'POST',
43	      headers: { 'Content-Type': 'application/json' },
44	      body: JSON.stringify({ projectId: project.id, amount: Number(amount) }),
45	    });
46	    setAmount('');
47	    await load();
48	  }
49	
50	  async function pay(id: number) {
51	    await fetch(`/api/invoices/${id}/pay`, { method: 'POST' });
52	    await load();
53	  }
54	
55	  const total = invoices.reduce((sum, inv) => sum + Number(inv.amount), 0);
56	
57	  return (
58	    <section data-testid="project-detail">
59	      <h2 data-testid="project-detail-name">{project.name}</h2>
60	
61	      <form data-testid="invoice-form" onSubmit={submit}>
62	        <input
63	          data-testid="invoice-form-amount"
64	          placeholder="Amount"
65	          value={amount}
66	          onChange={(e) => setAmount(e.target.value)}
67	        />
68	        <button data-testid="invoice-form-submit" type="submit">
69	          Add invoice
70	        </button>
71	        {amountError && (
72	          <p data-testid="invoice-form-amount-error" role="alert">
73	            {amountError}
74	          </p>
75	        )}
76	      </form>
77	
78	      <table data-testid="project-invoices-table">
79	        <tbody>
80	          {invoices.map((inv) => (
81	            <tr key={inv.id} data-testid={`invoice-row-${inv.id}`}>
82	              <td data-testid="invoice-amount">{money(inv.amount)}</td>
83	              <td data-testid="invoice-status">{inv.status}</td>
84	              <td>
85	                {inv.status !== 'PAID' && (
86	                  <button data-testid={`invoice-pay-${inv.id}`} onClick={() => pay(inv.id)}>
87	                    Mark paid
88	                  </button>
89	                )}
90	              </td>
91	            </tr>
92	          ))}
93	        </tbody>
94	      </table>
95	
96	      <p data-testid="project-invoices-total">{money(total)}</p>
97	    </section>
98	  );
99	}
100	
101	function ProjectsPage() {
102	  const [projects, setProjects] = useState<Project[]>([]);
103	  const [clients, setClients] = useState<Client[]>([]);
104	  const [name, setName] = useState('');
105	  const [clientId, setClientId] = useState('');
106	  const [openId, setOpenId] = useState<number | null>(null);
107	
108	  async function loadProjects() {
109	    const res = await fetch('/api/projects');
110	    setProjects(await res.json());
111	  }
112	
113	  async function loadClients() {
114	    const res = await fetch('/api/clients');
115	    setClients(await res.json());
116	  }
117	
118	  useEffect(() => {
119	    void loadProjects();
120	    void loadClients();
121	  }, []);
122	
123	  async function submit(e: React.FormEvent) {
124	    e.preventDefault();
125	    if (!name.trim() || !clientId) {
126	      return;
127	    }
128	    await fetch('/api/projects', {
129	      method: 'POST',
130	      headers: { 'Content-Type': 'application/json' },
131	      body: JSON.stringify({ name, clientId: Number(clientId) }),
132	    });
133	    setName('');
134	    setClientId('');
135	    await loadProjects();
136	  }
137	
138	  const open = projects.find((p) => p.id === openId) ?? null;
139	
140	  return (
141	    <section data-testid="projects">
142	      <form data-testid="project-form" onSubmit={submit}>
143	        <input
144	          data-testid="project-form-name"
145	          placeholder="Project name"
146	          value={name}
147	          onChange={(e) => setName(e.target.value)}
148	        />
149	        <select
